-- Catalog/body parity only. Runtime coverage is a separate authenticated read-only gate.
BEGIN;
SET TRANSACTION READ ONLY;
WITH required_columns(table_name,column_name) AS (VALUES ('hotel_stays','id'),('hotel_stays','dog_id'),('hotel_stays','checked_in_at'),('hotel_stays','checked_out_at'),('hotel_stays','checkout_previous_allocation_id'),('hotel_stays','version'),('hotel_stays','archived_at'),('dogs','id'),('dogs','name'),('hotel_rooms','id'),('hotel_rooms','name'),('hotel_rooms','room_type_id'),('hotel_room_types','id'),('hotel_room_types','name'),('hotel_room_allocations','id'),('hotel_room_allocations','capacity_reservation_id'),('hotel_room_allocations','room_id'),('hotel_room_allocations','allocated_from'),('hotel_room_allocations','allocated_until'),('hotel_room_allocations','request_id'),('hotel_room_allocations','version'),('hotel_room_allocations','archived_at'),('hotel_capacity_reservations','id'),('hotel_capacity_reservations','hotel_stay_id'),('hotel_capacity_reservations','physical_occupancy_id'),('hotel_capacity_reservations','source_kind'),('hotel_capacity_reservations','room_type_id'),('hotel_capacity_reservations','quantity'),('hotel_capacity_reservations','archived_at'),('hotel_capacity_reservations','reserved_from'),('hotel_capacity_reservations','reserved_until'),('hotel_capacity_reservations','version'),('entity_audit_events','entity_id'),('entity_audit_events','entity_type'),('entity_audit_events','module_code'),('entity_audit_events','before_data'),('entity_audit_events','after_data'),('entity_audit_events','request_id'),('hotel_physical_occupancy_members','id'),('hotel_physical_occupancy_members','hotel_stay_id'),('hotel_physical_occupancy_members','occupancy_id'),('hotel_physical_occupancy_members','joined_at'),('hotel_physical_occupancy_members','left_at'),('hotel_physical_occupancy_requests','occupancy_id'),('hotel_physical_occupancy_requests','operation_kind'),('family_booking_members','hotel_stay_id'),('family_booking_members','shared_room_group_id'),('long_stay_contracts','id'),('long_stay_contracts','current_hotel_stay_id'),('long_stay_monthly_occupancies','hotel_stay_id'),('long_stay_absence_events','id'),('long_stay_absence_events','hotel_stay_id'),('long_stay_absence_events','long_stay_contract_id'),('long_stay_absence_events','event_type'),('long_stay_absence_events','occurred_at'),('long_stay_absence_events','request_id'),('long_stay_absence_events','paired_leave_event_id'),('long_stay_absence_events','inventory_mode'),('long_stay_absence_events','released_allocation_id'),('long_stay_absence_events','released_capacity_id'),('long_stay_absence_events','returned_allocation_id'),('long_stay_absence_events','returned_room_id'),('long_stay_absence_events','return_capacity_id'),('long_stay_absence_events','guarantee_from'),('long_stay_absence_events','previous_room_id'),('long_stay_absence_events','is_open'),('long_stay_absence_events','archived_at'),('long_stay_operation_audit_events','id'),('long_stay_operation_audit_events','long_stay_contract_id'),('long_stay_operation_audit_events','absence_event_id'),('long_stay_operation_audit_events','operation_kind'),('long_stay_operation_audit_events','request_id'),('long_stay_operation_audit_events','canonical_payload')),
dependency(signature,body_md5) AS (VALUES ('public.hotel_shared_semantic_internal(text,jsonb)','1d7053f3a7a3472d1a00278798d48cf1'),('public.hotel_shared_chain_internal(text,jsonb,jsonb)','e444f7370b83e6e93d8f93fc6149fd30'),('public.hotel_shared_verified_segments_internal(uuid[])','9c255110adb3e596514a2a65a6bd91d6')),
checks AS (
 SELECT 'REQUIRED_COLUMNS' check_name, NOT EXISTS(SELECT 1 FROM required_columns r WHERE NOT EXISTS(SELECT 1 FROM information_schema.columns c WHERE c.table_schema='public' AND c.table_name=r.table_name AND c.column_name=r.column_name)) passed
 UNION ALL SELECT '008_DEPENDENCY_BODY_BASELINE',NOT EXISTS(SELECT 1 FROM dependency d WHERE md5(btrim((SELECT prosrc FROM pg_proc WHERE oid=to_regprocedure(d.signature)),E' \t\r\n')) IS DISTINCT FROM d.body_md5)
 UNION ALL SELECT 'AUTHORIZATION_DEPENDENCIES', to_regprocedure('auth.uid()') IS NOT NULL AND to_regprocedure('public.is_active_operation_member()') IS NOT NULL
 UNION ALL SELECT 'hotel_history_semantic_010(text,jsonb)',coalesce((SELECT md5(btrim(prosrc,E' \t\r\n'))='ec87cac6fa8d9519c1ac9c4c8cb2d1e8' AND prorettype='jsonb'::regtype AND provolatile='i' AND proconfig=ARRAY['search_path=public, pg_temp'] AND prosecdef=false FROM pg_proc WHERE oid=to_regprocedure('public.hotel_history_semantic_010(text,jsonb)')),false)
 UNION ALL SELECT 'hotel_history_chain_010(text,jsonb,jsonb)',coalesce((SELECT md5(btrim(prosrc,E' \t\r\n'))='a76e65dd66bf6dba34c2ab7d9efcb653' AND prorettype='boolean'::regtype AND provolatile='i' AND proconfig=ARRAY['search_path=public, pg_temp'] AND prosecdef=false FROM pg_proc WHERE oid=to_regprocedure('public.hotel_history_chain_010(text,jsonb,jsonb)')),false)
 UNION ALL SELECT 'hotel_history_individual_010(jsonb)',coalesce((SELECT md5(btrim(prosrc,E' \t\r\n'))='debfbe011b5d24045196046b537579b1' AND prorettype='jsonb'::regtype AND provolatile='i' AND proconfig=ARRAY['search_path=public, pg_temp'] AND prosecdef=false FROM pg_proc WHERE oid=to_regprocedure('public.hotel_history_individual_010(jsonb)')),false)
 UNION ALL SELECT 'hotel_history_shared_gate_010(jsonb,jsonb,jsonb,jsonb)',coalesce((SELECT md5(btrim(prosrc,E' \t\r\n'))='a715bf1c2be630c744ef18e3fb6714d9' AND prorettype='boolean'::regtype AND provolatile='i' AND proconfig=ARRAY['search_path=public, pg_temp'] AND prosecdef=false FROM pg_proc WHERE oid=to_regprocedure('public.hotel_history_shared_gate_010(jsonb,jsonb,jsonb,jsonb)')),false)
 UNION ALL SELECT 'get_hotel_historical_room_board(date)',coalesce((SELECT md5(btrim(prosrc,E' \t\r\n'))='09ac10531de414921fb60e14e488ea6f' AND prorettype='jsonb'::regtype AND provolatile='s' AND proconfig=ARRAY['search_path=public, pg_temp'] AND prosecdef=true FROM pg_proc WHERE oid=to_regprocedure('public.get_hotel_historical_room_board(date)')),false)
 UNION ALL SELECT 'EXECUTE_ACL',NOT EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=ANY(ARRAY[to_regprocedure('public.hotel_history_semantic_010(text,jsonb)'),to_regprocedure('public.hotel_history_chain_010(text,jsonb,jsonb)'),to_regprocedure('public.hotel_history_individual_010(jsonb)'),to_regprocedure('public.hotel_history_shared_gate_010(jsonb,jsonb,jsonb,jsonb)'),to_regprocedure('public.get_hotel_historical_room_board(date)')]) AND a.grantee IN (0,(SELECT oid FROM pg_roles WHERE rolname='anon'))) AND has_function_privilege('authenticated','public.get_hotel_historical_room_board(date)','EXECUTE')
 UNION ALL SELECT 'PRIVATE_HELPERS_NOT_EXPOSED',NOT EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=ANY(ARRAY[to_regprocedure('public.hotel_history_semantic_010(text,jsonb)'),to_regprocedure('public.hotel_history_chain_010(text,jsonb,jsonb)'),to_regprocedure('public.hotel_history_individual_010(jsonb)'),to_regprocedure('public.hotel_history_shared_gate_010(jsonb,jsonb,jsonb,jsonb)')]) AND a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('authenticated','service_role')))
)
SELECT check_name,CASE WHEN passed THEN 'PASS' ELSE 'FAIL' END status FROM checks UNION ALL SELECT 'OVERALL',CASE WHEN bool_and(passed) THEN 'PASS' ELSE 'FAIL' END FROM checks ORDER BY check_name;
ROLLBACK;
